1	import { useCallback, useEffect, useRef, useState } from "react";
2	import { lookupArtistLocation } from "../../shared/geocode.js";
3	import { devLog } from "../devLog.js";
4	import { classifyPollError } from "../pollError.js";
5	import { fetchCurrentlyPlaying, pause, play, skipToNext } from "../spotify.js";
6	import { MUTED, overlayCardStyle } from "../theme.js";
7	import { useLibraryArtists } from "../useLibraryArtists.js";
8	import BrowseLibraryButton from "./BrowseLibraryButton.jsx";
9	import LeafletMap from "./LeafletMap.jsx";
10	import LibraryLoadingBadge from "./LibraryLoadingBadge.jsx";
11	import NowPlayingCard from "./NowPlayingCard.jsx";
12	
13	const POLL_MS = 5_000;
14	// `unknown` marks this as the we-have-no-idea placeholder rather than a real
15	// resolved origin; LeafletMap keys its fly-to zoom off it (see UNKNOWN_ZOOM).
16	const PACIFIC_FALLBACK = {
17	  lat: 0,
18	  lng: -160,
19	  placeName: "Unknown location",
20	  unknown: true,
21	};
22	const SCOPE_WARNING = "Log out and back in to enable Browse Library";
23	
24	// A playback failure the user can act on beats an accurate one they can't.
25	// spotify.js already distinguishes these cases; collapsing them into one
26	// string was the whole reason "nothing playing + click an artist" read as a
27	// bug rather than as "open Spotify somewhere". Only NO_ACTIVE_DEVICE survives
28	// play()'s device fallback — by then it means nothing is open ANYWHERE, which
29	// no API call can fix.
30	const CONTROL_MESSAGES = {
31	  NO_ACTIVE_DEVICE: "Open Spotify on any device, then try again",
32	  PLAYBACK_UNAVAILABLE: "Spotify Premium is required to control playback",
33	  INSUFFICIENT_SCOPE: "Log out and back in to enable playback control",
34	};
35	const CONTROL_FALLBACK = "Playback control not available";
36	
37	// Fix 1 (final whole-branch review): explore mode's flagship feature — the
38	// clustered library map — must be reachable no matter what the now-playing
39	// poll is doing. These two states used to be full-screen early returns that
40	// replaced the map entirely, which meant BrowseLibraryButton and
41	// LibraryLoadingBadge only existed once something was playing. Both status
42	// messages are now a small overlay on top of the (always-rendered) map
43	// instead. "error" gets the same treatment as "idle": every case that lands
44	// here is an unrecognized *poll* error (classifyPollError already routes
45	// TOKEN_EXPIRED to a silent refresh and RATE_LIMITED to a retry) — never a
46	// hard auth failure — and the library-resolution loop is independent of the
47	// now-playing poll, so there's no reason a flaky currently-playing request
48	// should block browsing an already-fetched library.
49	const STATUS_OVERLAY_STYLE = {
50	  position: "fixed",
51	  top: "50%",
52	  left: "50%",
53	  transform: "translate(-50%, -50%)",
54	  zIndex: 900,
55	  padding: "16px 24px",
56	  textAlign: "center",
57	  // Nothing inside this overlay is interactive (just a message), and it now
58	  // sits on top of the always-rendered map — without this it swallows
59	  // clicks on any cluster/marker underneath it in explore mode while
60	  // idle/error.
61	  pointerEvents: "none",
62	  ...overlayCardStyle,
63	};
64	
65	// Fallback location for the scope warning / a control error when there's no
66	// NowPlayingCard to host the message (see displayMessage below). Mirrors
67	// NowPlayingCard's own message-slot styling (top-right, MUTED, 12px) so it
68	// reads as the same kind of notice.
69	//
70	// `color: MUTED` must come AFTER the `...overlayCardStyle` spread —
71	// overlayCardStyle sets `color: TEXT` (white), and object spread applies in
72	// source order, so putting MUTED first was silently overridden by white.
73	const STANDALONE_MESSAGE_STYLE = {
74	  position: "fixed",
75	  top: 16,
76	  right: 16,
77	  zIndex: 1000,
78	  padding: "10px 16px",
79	  fontSize: 12,
80	  textAlign: "center",
81	  ...overlayCardStyle,
82	  color: MUTED,
83	};
84	
85	export default function MapView({ token, onTokenExpired }) {
86	  const [track, setTrack] = useState(null);
87	  const [location, setLocation] = useState(null);
88	  const [status, setStatus] = useState("loading");
89	  const [controlMessage, setControlMessage] = useState(null);
90	  const [exploreMode, setExploreMode] = useState(false);
91	  const lastArtistRef = useRef(null);
92	  const refreshingRef = useRef(false);
93	  const mountedRef = useRef(true);
94	
95	  // Runs unconditionally from app boot regardless of exploreMode, per spec —
96	  // the background resolution loop keeps the library pre-populated so
97	  // explore mode is ready by the time the user opens it.
98	  const { artists, resolvedCount, total, scopeMissing, failedCount } =
99	    useLibraryArtists(token);
100	
101	  useEffect(() => {
102	    mountedRef.current = true;
103	    return () => {
104	      mountedRef.current = false;
105	    };
106	  }, []);
107	
108	  // Surfaces a stale-scope 403 (a session authorized before `user-follow-read`
109	  // was added — see the design doc's migration note) alongside the existing
110	  // transient controlMessage, without storing it in that same state. It's a
111	  // *persistent* condition (stays true until the user re-logs-in) riding on
112	  // a channel (`controlMessage`) that `runControl` unconditionally clears on
113	  // every successful play/pause/skip/select — storing the warning there
114	  // caused it to be silently wiped out by the next unrelated successful
115	  // control action. Deriving it instead means there's no state for anything
116	  // to clobber: a transient control error still wins while it's showing
117	  // (matches existing single-message-slot UI), and the scope warning simply
118	  // reappears on its own once that transient message clears, because
119	  // `scopeMissing` itself hasn't changed.
120	  const displayMessage =
121	    controlMessage ?? (scopeMissing ? SCOPE_WARNING : null);
122	
123	  // Fetch the currently-playing track and update state. Throws on API error so
124	  // callers (the poll loop and the control handlers) can apply their own
125	  // error handling. Both share this so a control action can refresh instantly.
126	  const syncNowPlaying = useCallback(async () => {
127	    const current = await fetchCurrentlyPlaying(token);
128	    if (!mountedRef.current) return;
129	
130	    if (!current) {
131	      devLog("[poll] nothing playing");
132	      setStatus("idle");
133	      return;
134	    }
135	
136	    // update track immediately; location catches up asynchronously
137	    setTrack(current);
138	    setStatus("playing");
139	    devLog(`[poll] now playing: ${current.artistName} – ${current.trackName}`);
140	
141	    if (current.artistName !== lastArtistRef.current) {
142	      lastArtistRef.current = current.artistName;
143	      devLog(`[poll] artist changed, looking up ${current.artistName}`);
144	      const loc = await lookupArtistLocation(current.artistName);
145	      if (mountedRef.current) setLocation(loc ?? PACIFIC_FALLBACK);
146	    }
147	  }, [token]);
148	
149	  // Shared TOKEN_EXPIRED refresh path, guarded so only one refresh runs at a
150	  // time even across overlapping poll/control errors.
151	  const refreshToken = useCallback(async () => {
152	    if (refreshingRef.current) return;
153	    refreshingRef.current = true;
154	    devLog("[poll] token expired, refreshing");
155	    try {
156	      await onTokenExpired();
157	    } finally {
158	      refreshingRef.current = false;
159	    }
160	  }, [onTokenExpired]);
161	
162	  useEffect(() => {
163	    let cancelled = false;
164	
165	    async function poll() {
166	      if (cancelled) return;
167	      try {
168	        await syncNowPlaying();
169	      } catch (err) {
170	        if (cancelled) return;
171	        const action = classifyPollError(err.message);
172	        if (action.type === "refresh") {
173	          await refreshToken();
174	          return;
175	        }
176	        if (action.type === "retry") {
177	          devLog(`[poll] rate limited, retrying in ${action.seconds}s`);
178	          // safe to schedule even near unmount: poll() checks cancelled at the top
179	          setTimeout(poll, action.seconds * 1000);
180	          return;
181	        }
182	        console.error("[poll] error:", err.message);
183	        setStatus("error");
184	      }
185	    }
186	
187	    poll();
188	    const id = setInterval(poll, POLL_MS);
189	    return () => {
190	      cancelled = true;
191	      clearInterval(id);
192	    };
193	  }, [syncNowPlaying, refreshToken]);
194	
195	  async function runControl(action) {
196	    try {
197	      await action();
198	      setControlMessage(null);
199	      return true;
200	    } catch (err) {
201	      if (err.message === "TOKEN_EXPIRED") {
202	        await refreshToken();
203	      } else {
204	        setControlMessage(CONTROL_MESSAGES[err.message] ?? CONTROL_FALLBACK);
205	      }
206	      return false;
207	    }
208	  }
209	
210	  async function handlePlayPause() {
